UPDATE public.help_articles SET resumo = 'Informe na conferência, antes de aceitar a maleta.', corpo = E'Na conferência da maleta, cada peça tem a linha "Unidades com problema".\n\n1. Toque em + para informar quantas unidades estão com problema.\n2. Escolha "Não veio na maleta" ou "Veio com defeito".\n3. Em "O que aconteceu?", escreva um motivo curto, por exemplo: "veio sem o fecho".\n4. Toque em "Aceitar maleta".\n\nO que você não informar é registrado como recebido em ordem. As peças com divergência não entram no seu saldo e aparecem no quadro "Divergências" de "Minha maleta".', revisado_em = current_date WHERE slug = 'divergencia';